package medium;public class BinaryTreeZigzagLevelOrderTraversal{static class TreeNode{int val;TreeNode l,r;TreeNode(int v){val=v;}}public static java.util.List<java.util.List<Integer>>zigzagLevelOrder(TreeNode r){java.util.List<java.util.List<Integer>>res=new java.util.ArrayList<>();if(r==null)return res;java.util.Queue<TreeNode>q=new java.util.LinkedList<>();q.offer(r);boolean lr=true;while(!q.isEmpty()){int s=q.size();java.util.List<Integer>l=new java.util.ArrayList<>();for(int i=0;i<s;i++){TreeNode n=q.poll();l.add(n.val);if(n.l!=null)q.offer(n.l);if(n.r!=null)q.offer(n.r);}if(!lr)java.util.Collections.reverse(l);res.add(l);lr=!lr;}return res;}}
